/**
 * 1. Simple pulsating circle that oscillates smoothly in a loop (0.0 -> 1.0)
 */
export const PULSING_CIRCLE_CODE = `
// Handcrafted sample: Pulsing Circle
ctx.fillStyle = '#0f172a';
ctx.fillRect(0, 0, width, height);

const cx = width / 2;
const cy = height / 2;
const baseRadius = Math.min(width, height) * 0.15;
const pulse = Math.sin(t * Math.PI * 2);
const radius = baseRadius * (1 + 0.25 * pulse);

// Outer glow
ctx.beginPath();
ctx.arc(cx, cy, radius * 1.2, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(56, 189, 248, 0.2)';
ctx.fill();

// Core circle
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fillStyle = '#38bdf8';
ctx.fill();
ctx.lineWidth = 4;
ctx.strokeStyle = '#e0f2fe';
ctx.stroke();
`.trim();

/**
 * 2. Deterministic procedural particles using opts.random() (Mulberry32)
 */
export const RANDOM_PARTICLES_CODE = `
// Handcrafted sample: Seeded Random Particles
ctx.fillStyle = '#09090b';
ctx.fillRect(0, 0, width, height);

const particleCount = 40;
for (let i = 0; i < particleCount; i++) {
  // Use opts.random() to determine base position, speed, and hue
  const baseX = opts.random() * width;
  const baseY = opts.random() * height;
  const speed = 50 + opts.random() * 150;
  const size = 3 + opts.random() * 6;

  // Seamless vertical upward float
  const y = (baseY - t * speed + height * 10) % height;
  const opacity = 0.4 + 0.6 * Math.sin((t + opts.random()) * Math.PI * 2);

  ctx.beginPath();
  ctx.arc(baseX, y, size, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(244, 63, 94, ' + Math.max(0.1, Math.abs(opacity)) + ')';
  ctx.fill();
}
`.trim();

